select string_agg(p.proname||'='||substr(md5(pg_get_functiondef(p.oid)),1,10), ' ' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('hdm_send_target','hdm_remove_target','hdm_open_chat','hdm_open_chat_internal','hdm_who_targeted_me','hdm_my_targets','hdm_has_interest','hdm_blocked_between','hdm_docs_guard','hdm_block_hidden_target','hdm_plan_row','hdm_plan_of')
